    'SOP framework with version control.',
    '# SOP Document Generator\nfrom datetime import date\n\ndef generate_sop(title, owner, steps, checks, troubleshooting):\n    sop = []\n    sop.append("=" * 60)\n    sop.append(f"STANDARD OPERATING PROCEDURE")\n    sop.append("=" * 60)\n    sop.append(f"Title: {title}")\n    sop.append(f"Version: 1.0")\n    sop.append(f"Effective: {date.today()}")\n    sop.append(f"Owner: {owner}")\n    sop.append("─" * 60)\n    sop.append(f"\\nPROCEDURE STEPS:")\n    for i, step in enumerate(steps, 1):\n        sop.append(f"  {i}. {step}")\n    sop.append(f"\\nQUALITY CHECKS:")\n    for check in checks:\n        sop.append(f"  [ ] {check}")\n    sop.append(f"\\nTROUBLESHOOTING:")\n    for issue, fix in troubleshooting:\n        sop.append(f"  Problem: {issue}")\n        sop.append(f"  Solution: {fix}\\n")\n    return "\\n".join(sop)\n\nprint(generate_sop(\n    title="Order Picking Process",\n    owner="Warehouse Manager",\n    steps=[\n        "Log into WMS and retrieve pick list",\n        "Verify pick cart is clean and labeled",\n        "Navigate to first location using system-guided path",\n        "Scan location barcode to confirm position",\n        "Pick quantity shown, scan item barcode",\n        "IF damaged item: flag in WMS, skip, continue",\n        "Place item in designated cart slot",\n        "Repeat steps 3-7 for all items",\n        "Deliver cart to packing station",\n        "Confirm pick completion in WMS",\n    ],\n    checks=[\n        "All items scanned (no manual overrides)",\n        "Quantities match pick list",\n        "No damaged items included",\n        "Cart labeled with order number",\n    ],\n    troubleshooting=[\n        ("Item not in expected location", "Check alternate locations in WMS, then report discrepancy"),\n        ("Barcode unreadable", "Enter SKU manually, flag for label replacement"),\n        ("Insufficient quantity", "Pick available, create backorder for remainder"),\n    ]\n))',
